<?php /* Simulate what happens on production when a non-admin finance user hits invoices.index */ $u = App\Models\User::where("email", "advisor@sns.com")->first(); auth()->login($u); echo "User: " . $u->email . PHP_EOL; echo "isAdmin: " . ($u->isAdmin() ? "YES" : "NO") . PHP_EOL; echo "preferredHome: " . $u->preferredHomeRouteName() . PHP_EOL; echo "viewAny invoice: " . (Gate::allows("viewAny", App\Models\Invoice::class) ? "YES" : "NO") . PHP_EOL; /* Now try loading the index */ try { $c = app()->make(App\Http\Controllers\Web\InvoiceWebController::class); $view = $c->index(); echo "index() SUCCESS" . PHP_EOL; } catch (\Illuminate\Auth\Access\AuthorizationException $e) { echo "AuthorizationException: " . $e->getMessage() . PHP_EOL; } catch (\Exception $e) { echo "EXCEPTION: " . get_class($e) . " - " . $e->getMessage() . PHP_EOL; echo $e->getTraceAsString() . PHP_EOL; }
